[metadata] {"type": "create", "filePath": "/app/output/css/styles.css", "content": "/* ============================================
   RedRoom Fitness — Design System & Styles
   ============================================ */

/* --- CSS Custom Properties --- */
:root {
  --bg-primary: #0a0a0a;
  --bg-secondary: #141414;
  --bg-card: #1a1a1a;
  --bg-card-hover: #222222;
  --accent: #E63946;
  --accent-hover: #ff1a2d;
  --accent-dark: #b82d38;
  --accent-glow: rgba(230, 57, 70, 0.25);
  --text-primary: #ffffff;
  --text-secondary: #b0b0b0;
  --text-muted: #666666;
  --border-color: #2a2a2a;
  --border-light: #333333;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --container-max: 1200px;
  --section-padding: 100px;
  --nav-height: 70px;
  --transition-fast: 0.2s ease;
  --transition-base: 0.3s ease;
  --transition-slow: 0.5s ease;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

input {
  font-family: inherit;
  border: none;
  outline: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.1;
}

h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); }
h2 { font-size: clamp(2rem, 4vw, 3.2rem); }
h3 { font-size: clamp(1.4rem, 2.5vw, 2rem); }
h4 { font-size: clamp(1.1rem, 1.8vw, 1.4rem); }

p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-padding) 0;
}

.section--dark {
  background: var(--bg-secondary);
}

.section--red {
  background: var(--accent);
}

.section--red p,
.section--red h2,
.section--red h3 {
  color: var(--text-primary);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 16px 40px;
  border-radius: 4px;
  font-size: 1rem;
  transition: all var(--transition-base);
  min-height: 52px;
}

.btn--primary {
  background: var(--accent);
  color: var(--text-primary);
}

.btn--primary:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 30px var(--accent-glow);
  transform: translateY(-1px);
}

.btn--outline {
  background: transparent;
  color: var(--text-primary);
  border: 2px solid var(--text-primary);
}

.btn--outline:hover {
  background: var(--text-primary);
  color: var(--bg-primary);
}

.btn--large {
  padding: 20px 56px;
  font-size: 1.15rem;
  min-height: 60px;
}

.btn--small {
  padding: 10px 24px;
  font-size: 0.85rem;
  min-height: 40px;
}

.btn-group {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* --- Top Promo Bar --- */
.top-promo {
  background: var(--accent);
  text-align: center;
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.top-promo a {
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}

.top-promo a:hover {
  color: var(--bg-primary);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--nav-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.nav--scrolled {
  background: rgba(10, 10, 10, 0.95);
  backdrop-filter: blur(12px);
  box-shadow: 0 2px 20px rgba(0, 0, 0, 0.5);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav__logo span {
  color: var(--accent);
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 28px;
}

.nav__links a {
  font-family: var(--font-heading);
  font-size: 0.82rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}

.nav__links a:hover,
.nav__links a.active {
  color: var(--text-primary);
}

.nav__links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
}

.nav__utility {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav__utility a {
  font-family: var(--font-heading);
  font-size: 0.78rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav__utility a:hover {
  color: var(--text-primary);
}

.nav__book-btn {
  background: var(--accent);
  color: var(--text-primary) !important;
  padding: 8px 20px;
  border-radius: 3px;
  font-weight: 600 !important;
}

.nav__book-btn:hover {
  background: var(--accent-hover) !important;
}

/* Mobile menu toggle */
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  cursor: pointer;
  z-index: 1001;
}

.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-base);
}

.nav__mobile-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav__mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav__mobile-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile menu overlay */
.nav__mobile-menu {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(10, 10, 10, 0.98);
  z-index: 999;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.nav__mobile-menu.open {
  display: flex;
  opacity: 1;
}

.nav__mobile-menu a {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav__mobile-menu a:hover {
  color: var(--accent);
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  padding-top: var(--nav-height);
}

.hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero__bg-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(10, 10, 10, 0.6) 0%,
    rgba(10, 10, 10, 0.4) 40%,
    rgba(10, 10, 10, 0.85) 100%
  );
