}

.hero__subtitle {
  font-size: clamp(1rem, 2vw, 1.2rem);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* --- Community Promo --- */
.community-promo {
  text-align: center;
}

.community-promo h2 {
  margin-bottom: 20px;
}

.community-promo p {
  max-width: 650px;
  margin: 0 auto 32px;
  font-size: 1.05rem;
}

/* --- Two Ways --- */
.two-ways {
  text-align: center;
}

.two-ways__heading {
  margin-bottom: 48px;
}

.two-ways__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

.two-ways__card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 48px 36px;
  text-align: center;
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
