.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  transform: scaleX(0);
  transition: transform var(--transition-base);
}

.two-ways__card:hover::before {
  transform: scaleX(1);
}

.two-ways__card:hover {
  border-color: var(--border-light);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

.two-ways__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  background: var(--accent-glow);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
}

.two-ways__card h3 {
