  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .carousel__slide {
    min-width: calc(80% - 16px);
  }

  .footer__grid {
    grid-template-columns: 1fr;
  }

  .newsletter__form {
    flex-direction: column;
  }

  .schedule-table {
    font-size: 0.85rem;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 12px 14px;
  }
}

