    });
  }

  function next() {
    currentIndex = currentIndex >= maxIndex ? 0 : currentIndex + 1;
    updateCarousel();
  }

  function prev() {
    currentIndex = currentIndex <= 0 ? maxIndex : currentIndex - 1;
    updateCarousel();
  }

  if (nextBtn) nextBtn.addEventListener('click', next);
  if (prevBtn) prevBtn.addEventListener('click', prev);

  createDots();

  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      slidesPerView = getSlidesPerView();
      maxIndex = Math.max(0, slides.length - slidesPerView);
      if (currentIndex > maxIndex) currentIndex = maxIndex;
      createDots();
      updateCarousel();
    }, 150);
  });

  // Touch/swipe support
  let startX = 0;
  let isDragging = false;

  track.addEventListener('touchstart', (e) => {
    startX = e.touches[0].clientX;
    isDragging = true;
  }, { passive: true });

  track.addEventListener('touchmove', (e) => {
    if (!isDragging) return;
  }, { passive: true });

  track.addEventListener('touchend', (e) => {
    if (!isDragging) return;
    isDragging = false;
    const endX = e.changedTouches[0].clientX;
    const diff = startX - endX;
    if (Math.abs(diff) > 50) {
      diff > 0 ? next() : prev();
    }
  }, { passive: true });
}

/* --- Floor/Treadmill Toggle --- */
function initToggle() {
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const toggleContents = document.querySelectorAll('.toggle-content');

  if (toggleBtns.length === 0) return;

  toggleBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const target = btn.dataset.target;

      toggleBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      toggleContents.forEach(content => {
        content.classList.toggle('active', content.id === target);
      });
    });
  });
}

/* --- Instructor Filter --- */
function initInstructorFilter() {
  const filterSelect = document.querySelector('.filter-select');
  const cards = document.querySelectorAll('.instructor-card');

  if (!filterSelect || cards.length === 0) return;

  filterSelect.addEventListener('change', () => {
    const location = filterSelect.value;

    cards.forEach(card => {
      const cardLocation = card.dataset.location;
      if (location === 'all' || cardLocation === location) {
        card.classList.remove('hidden');
      } else {
        card.classList.add('hidden');
      }
    });
  });
}

/* --- FAQ Accordion --- */
function initAccordion() {
  const items = document.querySelectorAll('.faq-item');

  if (items.length === 0) return;

  items.forEach(item => {
    const question = item.querySelector('.faq-item__question');
    question.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all items (single-open behavior)
      items.forEach(i => i.classList.remove('active'));

      // Open clicked item if it wasn't already open
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });
}

/* --- Newsletter Validation --- */
function initNewsletter() {
  const forms = document.querySelectorAll('.newsletter__form');

  forms.forEach(form => {
    const input = form.querySelector('.newsletter__input');
    const message = form.querySelector('.newsletter__message');

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = input.value.trim();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      // Reset
      input.classList.remove('error', 'success');
      message.classList.remove('error', 'success');
      message.textContent = '';

      if (!email) {
        input.classList.add('error');
        message.classList.add('error');
        message.textContent = 'Please enter your email address.';
        return;
      }

      if (!emailRegex.test(email)) {
        input.classList.add('error');
        message.classList.add('error');
        message.textContent = 'Please enter a valid email address.';
        return;
      }

      // Success
      input.classList.add('success');
      message.classList.add('success');
      message.textContent = 'Welcome to the RedRoom community! Check your inbox.';
      input.value = '';
    });
  });
}

